-- CAPEX-PROPOSED-MEASURES (bim-ootb prompts/CAPEX_DASHBOARD.md §5.38; §6 Q4 and Q3 PROPOSED DEFAULTS, awaiting Sysnova): three PA measures, ids 1000040-1000042, every Name ends '(proposed)'. Same convention as 202611032000_CAPEX-G2.sql.
-- Contract = completed purchase orders on a project. Verified = actual cost (ProjectBalanceAmt) of projects with at least one completed Project Issue: iDempiere adds an issue's cost to ProjectBalanceAmt itself, so it OVERLAPS Actual Cost.
-- Forecast = EAC = Spent + (Budget - Done) / CPI, CPI = Done / Spent = Spent + (Budget - Done) * Spent / Done, over active projects with Spent > 0 and Done > 0 (Done = SUM of completed C_ProjectPhase.PlannedAmt). USD (C_Currency_ID 100) like the Approved Budget goals.
-- Restore: DELETE FROM PA_Goal WHERE PA_Measure_ID BETWEEN 1000040 AND 1000042; DELETE FROM PA_Measure WHERE PA_Measure_ID BETWEEN 1000040 AND 1000042; DELETE FROM PA_MeasureCalc WHERE PA_MeasureCalc_ID BETWEEN 1000040 AND 1000042;
SELECT register_migration_script('202611111310_CAPEX-PROPOSED-MEASURES.sql') FROM dual;

-- CAPEX Contract Committed USD (proposed)
INSERT INTO PA_MeasureCalc (PA_MeasureCalc_ID,AD_Client_ID,AD_Org_ID,IsActive,Created,CreatedBy,Updated,UpdatedBy,Name,Description,SelectClause,WhereClause,DateColumn,OrgColumn,KeyColumn,AD_Table_ID,EntityType,PA_MeasureCalc_UU)
SELECT 1000040,11,0,'Y',TO_TIMESTAMP('2026-11-11 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-11 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,'CAPEX Contract Committed USD (proposed)','Q4 proposed: SUM(GrandTotal) of completed purchase orders on a project, USD','SELECT COALESCE(SUM(C_Order.GrandTotal),0) FROM C_Order','WHERE C_Order.IsSOTrx=''N'' AND C_Order.DocStatus=''CO'' AND C_Order.C_Project_ID>0 AND C_Order.C_Currency_ID=100','C_Order.DateOrdered','C_Order.AD_Org_ID','C_Order.C_Order_ID',(SELECT AD_Table_ID FROM AD_Table WHERE TableName='C_Order'),'U','5a0c3e1e-0b7d-4c1e-9f3a-cafe00010040' FROM dual WHERE NOT EXISTS (SELECT 1 FROM PA_MeasureCalc WHERE PA_MeasureCalc_ID=1000040)
;
INSERT INTO PA_Measure (PA_Measure_ID,AD_Client_ID,AD_Org_ID,IsActive,Created,CreatedBy,Updated,UpdatedBy,Name,Description,MeasureType,MeasureDataType,PA_MeasureCalc_ID,PA_Measure_UU)
SELECT 1000040,11,0,'Y',TO_TIMESTAMP('2026-11-11 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-11 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,'CAPEX Contract Committed USD (proposed)','Q4 proposed: SUM(GrandTotal) of completed purchase orders on a project, USD','C','S',1000040,'5a0c3e1e-0b7d-4c1e-9f3a-cafe00020040' FROM dual WHERE NOT EXISTS (SELECT 1 FROM PA_Measure WHERE PA_Measure_ID=1000040)
;
-- CAPEX Verified Cost USD (proposed)
INSERT INTO PA_MeasureCalc (PA_MeasureCalc_ID,AD_Client_ID,AD_Org_ID,IsActive,Created,CreatedBy,Updated,UpdatedBy,Name,Description,SelectClause,WhereClause,DateColumn,OrgColumn,KeyColumn,AD_Table_ID,EntityType,PA_MeasureCalc_UU)
SELECT 1000041,11,0,'Y',TO_TIMESTAMP('2026-11-11 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-11 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,'CAPEX Verified Cost USD (proposed)','Q4 proposed: ProjectBalanceAmt of projects with a completed Project Issue, USD (overlaps Actual Cost: iDempiere adds the issue cost to it)','SELECT COALESCE(SUM(C_Project.ProjectBalanceAmt),0) FROM C_Project','WHERE C_Project.C_Currency_ID=100 AND EXISTS (SELECT 1 FROM C_ProjectIssue i WHERE i.C_Project_ID=C_Project.C_Project_ID AND i.Processed=''Y'')','C_Project.Created','C_Project.AD_Org_ID','C_Project.C_Project_ID',(SELECT AD_Table_ID FROM AD_Table WHERE TableName='C_Project'),'U','5a0c3e1e-0b7d-4c1e-9f3a-cafe00010041' FROM dual WHERE NOT EXISTS (SELECT 1 FROM PA_MeasureCalc WHERE PA_MeasureCalc_ID=1000041)
;
