-- CAPEX Forecast Cost at Completion USD (proposed)
INSERT INTO PA_MeasureCalc (PA_MeasureCalc_ID,AD_Client_ID,AD_Org_ID,IsActive,Created,CreatedBy,Updated,UpdatedBy,Name,Description,SelectClause,WhereClause,DateColumn,OrgColumn,KeyColumn,AD_Table_ID,EntityType,PA_MeasureCalc_UU)
SELECT 1000042,11,0,'Y',TO_TIMESTAMP('2026-11-11 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-11 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,'CAPEX Forecast Cost at Completion USD (proposed)','Q3 proposed: EAC = Spent + (Budget - Done) / CPI with CPI = Done / Spent; active projects with Spent and Done above 0, USD','SELECT COALESCE(SUM(C_Project.ProjectBalanceAmt + (C_Project.PlannedAmt - (SELECT SUM(ph.PlannedAmt) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=C_Project.C_Project_ID AND ph.IsComplete=''Y'')) * C_Project.ProjectBalanceAmt / (SELECT SUM(ph.PlannedAmt) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=C_Project.C_Project_ID AND ph.IsComplete=''Y'')),0) FROM C_Project','WHERE C_Project.C_Currency_ID=100 AND C_Project.IsActive=''Y'' AND C_Project.Processed=''N'' AND C_Project.ProjectBalanceAmt>0 AND (SELECT SUM(ph.PlannedAmt) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=C_Project.C_Project_ID AND ph.IsComplete=''Y'')>0','C_Project.Created','C_Project.AD_Org_ID','C_Project.C_Project_ID',(SELECT AD_Table_ID FROM AD_Table WHERE TableName='C_Project'),'U','5a0c3e1e-0b7d-4c1e-9f3a-cafe00010042' FROM dual WHERE NOT EXISTS (SELECT 1 FROM PA_MeasureCalc WHERE PA_MeasureCalc_ID=1000042)
;
INSERT INTO PA_Measure (PA_Measure_ID,AD_Client_ID,AD_Org_ID,IsActive,Created,CreatedBy,Updated,UpdatedBy,Name,Description,MeasureType,MeasureDataType,PA_MeasureCalc_ID,PA_Measure_UU)
SELECT 1000042,11,0,'Y',TO_TIMESTAMP('2026-11-11 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-11 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,'CAPEX Forecast Cost at Completion USD (proposed)','Q3 proposed: EAC = Spent + (Budget - Done) / CPI with CPI = Done / Spent; active projects with Spent and Done above 0, USD','C','S',1000042,'5a0c3e1e-0b7d-4c1e-9f3a-cafe00020042' FROM dual WHERE NOT EXISTS (SELECT 1 FROM PA_Measure WHERE PA_Measure_ID=1000042)
;
